class Node:
    def __init__(self):
        self.children = {}               # char -> Node
        self.end = False                 # a whole word stops here

class Trie:
    def __init__(self):
        self.root = Node()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = Node()
            node = node.children[ch]
        node.end = True

    def _walk(self, s: str):             # node at the end of s, or None
        node = self.root
        for ch in s:
            if (node := node.children.get(ch)) is None:
                return None
        return node

    def search(self, word: str) -> bool:
        node = self._walk(word)
        return node is not None and node.end   # a prefix alone is not a word

    def starts_with(self, prefix: str) -> bool:
        return self._walk(prefix) is not None
